#![allow(dead_code)]
use core::ffi::c_void;
unsafe extern "C" { pub fn malloc(n: usize) -> *mut c_void; pub fn free(p: *mut c_void); pub fn realloc(p: *mut c_void, n: usize) -> *mut c_void; }
pub unsafe fn buf_free(p: *mut u8, _n: usize) { unsafe { free(p.cast()) } }
#[derive(Clone, Copy, Debug, Default)] pub struct Lib16;
ffibox::impl_clendrop!(Lib16, buf_free);
ffibox::impl_clenalloc!(Lib16, malloc, align = 16, realloc = realloc);
#[derive(Clone, Copy, Debug, Default)] pub struct Lib1;
ffibox::impl_clendrop!(Lib1, buf_free);
ffibox::impl_clenalloc!(Lib1, malloc);
#[derive(Debug, Default)] pub struct NoCopy;
ffibox::impl_clendrop!(NoCopy, buf_free);
ffibox::impl_clenalloc!(NoCopy, malloc, align = 16);
/// A native-layout struct: no repr(C), no CCell.
#[derive(Debug, PartialEq)] pub struct Foo { pub a: u64, pub b: bool }
const _: () = assert!(!core::mem::needs_drop::<Foo>());
EOF
cat > examples/ok.rs <<'EOF'
#![feature(allocator_api)]
use ffibox::{CAllocator, CVec}; use probe::*;
fn main() {
    let a = CAllocator::new(Lib16);
    let b = a.try_box(Foo { a: 7, b: true }).unwrap();
    let (p, a2) = Box::into_raw_with_allocator(b);
    println!("box ptr {p:p}");
    let b = unsafe { Box::from_raw_in(p, a2) };
    assert_eq!(*b, Foo { a: 7, b: true }); drop(b);
    let mut v = Vec::new_in(a); v.try_reserve(8).unwrap();
    for i in 0..5 { v.push(Foo { a: i, b: false }); }
    let c: CVec<Foo, CAllocator<Lib16>> = CVec::try_from(v).unwrap();
    let (p, n) = c.into_raw_parts();
    println!("run {p:p} len {n}");
    let v = unsafe { Vec::from_raw_parts_in(p, n, n, a) };
    assert_eq!(v.len(), 5); println!("ok");
}
EOF
