w e_pin <<'EOF'
use ffibox::CAllocator; use probe::*;
fn main() { let b = CAllocator::new(Lib16).try_box(Foo { a: 1, b: false }).unwrap(); let _ = Box::into_pin(b); }
EOF
w e_copy <<'EOF'
use ffibox::CAllocator; use probe::*;
fn main() { let _ = CAllocator::new(NoCopy).try_box(Foo { a: 1, b: false }); }
EOF
